import type { ComponentPropsWithoutRef, ReactNode } from 'react';

/**
 * The two buttons this kind of page needs, and no more.
 *
 * Hover changes colour and nothing else: no scaling, no glow. Both are anchors because on these
 * sites every action is a link — to WhatsApp, to a phone number, to a section further down.
 */
interface ButtonProps extends ComponentPropsWithoutRef<'a'> {
  children: ReactNode;
  variant?: 'primary' | 'secondary';
}

export function Button({ children, variant = 'primary', className = '', ...props }: ButtonProps) {
  const styles =
    variant === 'primary'
      ? 'bg-accent text-surface hover:bg-accent-strong'
      : 'border border-ink/15 text-ink hover:border-ink/40';

  return (
    <a
      className={`inline-flex items-center gap-2 rounded-control px-5 py-3 text-sm font-semibold transition-colors duration-150 ${styles} ${className}`}
      {...props}
    >
      {children}
    </a>
  );
}

import { useMemo, useState } from 'react';
import { MessageCircle, X } from 'lucide-react';
import { Section, Eyebrow, SectionTitle } from './Section';
import { Button } from './Button';
import { site, whatsappLink, type Product } from '../lib/site';

/**
 * The section that convinces a shop owner, and the one most often left out.
 *
 * Real items with photo, name, category and price, filters that actually filter, and a quick view
 * that opens the item with a WhatsApp action carrying its name already written. All of it is local
 * state over an array — no routing, no backend, nothing to provision before it can be shown.
 */
interface CatalogueProps {
  eyebrow: string;
  title: string;
  products: Product[];
  ground?: 'bg' | 'surface' | 'tint';
}

export function Catalogue({ eyebrow, title, products, ground = 'surface' }: CatalogueProps) {
  const categories = useMemo(() => ['Todos', ...new Set(products.map((p) => p.category))], [products]);
  const [active, setActive] = useState('Todos');
  const [open, setOpen] = useState<Product | null>(null);

  const shown = active === 'Todos' ? products : products.filter((p) => p.category === active);

  return (
    <Section ground={ground} id="catalogo">
      <Eyebrow>{eyebrow}</Eyebrow>
      <SectionTitle>{title}</SectionTitle>

      <div className="mt-8 flex flex-wrap gap-2">
        {categories.map((category) => (
          <button
            key={category}
            onClick={() => setActive(category)}
            className={`rounded-full border px-4 py-1.5 text-sm transition-colors duration-150 ${
              active === category
                ? 'border-accent bg-accent text-surface'
                : 'border-ink/15 bg-transparent text-muted hover:border-ink/40 hover:text-ink'
            }`}
          >
            {category}
          </button>
        ))}
      </div>

      <div className="mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
        {shown.map((product) => (
          <button key={product.name} onClick={() => setOpen(product)} className="lift group bg-transparent text-left">
            <img
              src={product.imageUrl}
              alt={product.imageAlt}
              loading="lazy"
              width={940}
              height={650}
              className="aspect-[4/3] w-full rounded-control object-cover"
            />
            <p className="mt-3 text-xs uppercase tracking-wide text-muted">{product.category}</p>
            <h3 className="mt-1 font-heading">{product.name}</h3>
            <p className="mt-1 font-semibold text-accent">{product.price}</p>
          </button>
        ))}
      </div>

      {open && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-ink/70 p-4"
          role="dialog"
          aria-modal="true"
          aria-label={open.name}
          onClick={() => setOpen(null)}
        >
          <div
            className="relative max-h-[90vh] w-full max-w-3xl overflow-auto rounded-panel bg-surface"
            onClick={(event) => event.stopPropagation()}
          >
            <button
              onClick={() => setOpen(null)}
              aria-label="Cerrar"
              className="absolute right-4 top-4 rounded-full bg-surface/90 p-2"
            >
              <X className="h-5 w-5" />
            </button>

            <img src={open.imageUrl} alt={open.imageAlt} className="aspect-[16/9] w-full object-cover" />

            <div className="p-8">
              <p className="text-xs uppercase tracking-wide text-muted">{open.category}</p>
              <h3 className="mt-1 text-section font-heading">{open.name}</h3>
              <p className="mt-3 max-w-measure text-muted">{open.description}</p>
              <p className="mt-4 text-2xl font-semibold text-accent">{open.price}</p>

              <Button
                href={whatsappLink(`Hola ${site.name}, me interesa ${open.name}.`)}
                target="_blank"
                rel="noreferrer"
                className="mt-6"
              >
                <MessageCircle className="h-4 w-4" />
                Consultar por WhatsApp
              </Button>
            </div>
          </div>
        </div>
      )}
    </Section>
  );
}

import { Section, Eyebrow, SectionTitle } from './Section';

/**
 * Three full-bleed photographs with a title over each — one per line of business.
 *
 * Not three cards. Three cards in a row is the answer a generated page gives to every section, and
 * a business with three real lines deserves to have them shown at photograph size.
 */
interface CategoryTriptychProps {
  eyebrow: string;
  title: string;
  ground?: 'bg' | 'surface' | 'tint';
  categories: { name: string; line: string; imageUrl: string; imageAlt: string; href?: string }[];
}

export function CategoryTriptych({ eyebrow, title, categories, ground = 'bg' }: CategoryTriptychProps) {
  return (
    <Section ground={ground} id="categorias">
      <Eyebrow>{eyebrow}</Eyebrow>
      <SectionTitle>{title}</SectionTitle>

      <div className="mt-12 grid gap-4 md:grid-cols-3">
        {categories.map((category) => (
          <a
            key={category.name}
            href={category.href ?? '#catalogo'}
            className="lift group relative isolate flex min-h-[26rem] items-end overflow-hidden rounded-control"
          >
            <img
              src={category.imageUrl}
              alt={category.imageAlt}
              loading="lazy"
              className="absolute inset-0 -z-10 h-full w-full object-cover"
            />
            <div className="absolute inset-0 -z-10 bg-gradient-to-t from-ink/85 via-ink/25 to-transparent" aria-hidden />

            <div className="p-7 text-surface">
              <h3 className="text-2xl font-heading">{category.name}</h3>
              <p className="mt-2 max-w-[28ch] text-sm opacity-85">{category.line}</p>
            </div>
          </a>
        ))}
      </div>
    </Section>
  );
}

