@tailwind base;
@tailwind components;
@tailwind utilities;

/*
 * Abre un contenedor de consulta para que `text-hero` mida contra este ancho y no contra la
 * ventana. Va en la columna de texto del hero, no en el hero entero: lo que tiene que decidir el
 * tamaño del titular es el espacio que el titular tiene.
 */
.mide-por-columna {
  container-type: inline-size;
}

/*
 * Las nueve paletas sectoriales del design kit, verificadas como conjuntos.
 *
 * Elegí la fila que le corresponde al negocio, pegá sus siete valores en :root y borrá el resto.
 * Nunca mezcles dos filas: su contraste se verificó junta, no cruzada.
 *
 * `tint` es el tercer fondo y es el token que faltaba. Sin él una página queda con dos grounds y
 * los dos son grises. Medido en un sitio generado de verdad: el 93 por ciento del área pintada
 * era blanco o casi blanco, y el acento sólido ocupaba el 0,5. `tint` lleva el tono del acento a
 * un fondo entero, que es lo que hace que una página clara se sienta con color en vez de lavada.
 *
 * CLARAS                         bg          / surface     / tint          / ink         / muted       / accent     / accent-strong  peso
 * turismo, aventura, hotelería   247 245 240 / 255 255 255 / 219 239 234  / 11 51 45    / 79 108 102  / 0 111 98   / 0 80 70     600
 * gastronomía, café, catering    250 247 242 / 255 255 255 / 250 231 229  / 54 26 25    / 109 83 81   / 125 42 43  / 94 26 28    600
 * belleza, bienestar             248 247 245 / 255 255 255 / 223 241 232  / 9 43 31     / 80 105 94   / 0 112 80   / 0 84 60     300
 * comercio, tienda, retail       250 248 244 / 255 255 255 / 249 233 223  / 46 24 7     / 109 88 74   / 164 86 10  / 124 64 8    600
 * oficios, construcción          245 246 248 / 255 255 255 / 223 236 249  / 8 30 48     / 76 94 111   / 0 85 140   / 0 60 105    700
 * salud, legal, profesional      247 247 245 / 255 255 255 / 227 236 251  / 14 26 47    / 79 90 110   / 23 56 119  / 11 38 89    600
 *
 * OSCURAS — no son la variante atrevida de las claras, dicen otra cosa: oficio, fuerza y comercio
 * nocturno. Si el rótulo, los uniformes o el local del cliente son oscuros, eso lo decide.
 * turismo/aventura (dark)        15 26 23    / 22 36 31    / 29 45 40     / 210 251 239 / 135 164 156 / 53 183 156 / 121 218 196 600
 * joyería, perfumería (dark)     18 18 18    / 28 26 25    / 39 34 22     / 253 241 208 / 165 156 133 / 201 162 39 / 228 194 92  300
 * taller, motos, deporte (dark)  20 20 22    / 30 30 34    / 49 35 33     / 255 237 235 / 171 143 140 / 225 29 46  / 179 18 31   800
 */
:root {
  --bg: 247 245 240;
  --surface: 255 255 255;
  --tint: 219 239 234;
  --ink: 11 51 45;
  --muted: 79 108 102;
  --accent: 0 111 98;
  --accent-strong: 0 80 70;

  /* must match the <link> in index.html — a family that is not loaded falls through silently */
  --font-display: 'Bricolage Grotesque';
  --font-body: 'Karla';

  /* the display weight of the sector row above; font-display uses it */
  --weight-display: 600;
}

@layer base {
  body {
    @apply bg-bg text-ink font-body text-body antialiased;
  }

  h1,
  h2,
  h3 {
    @apply font-display font-heading text-balance;
  }

  /*
   * One rule instead of remembering it on every control. The design kit asks for a visible focus
   * ring everywhere, and a page that removes it is failing people who navigate by keyboard.
   */
  :focus-visible {
    @apply outline outline-2 outline-offset-2 outline-accent;
  }
}

/* the marquee band's only animation; the class that uses it is animate-[marquee_28s_linear_infinite] */
@keyframes marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

@layer utilities {
  /* the whole motion repertoire: a card lift and a link underline, nothing else */
  .lift {
    @apply transition-[transform,box-shadow] duration-150 will-change-transform hover:-translate-y-0.5 hover:shadow-raised;
  }

  @media (prefers-reduced-motion: reduce) {
    .lift {
      @apply transition-none hover:translate-y-0;
    }
  }
}

/**
